@pytest.mark.asyncio
async def test_unified_live_disconnect_abandons_edit_and_reconnect_keeps_pause(
    tmp_path: Path, process_services: ProcessServices
) -> None:
    """*Prepare*: A live app server with a queued message held by its connection.
    *Do*: Disconnect and attach a new connection to the same Session.
    *Assert*: The original queue survives paused and the editor has been cleared.
    """
    # Prepare
    config = build_test_vibe_config(
        session_logging=SessionLoggingConfig(enabled=True, save_dir=str(tmp_path))
    )
    host = _harness_backend_host(config)
    started = await host.start(SessionStartParams())
    backend = started.backend
    assert isinstance(backend, SessionBackendQueuedTurnEditing)
    queued = await backend.enqueue_turn(
        TurnEnqueueParams(
            session_id=backend.session_id,
            idempotency_key="queued",
            entries=[
                TurnUserInputEntry(content=[SessionTextContentBlock(text="original")])
            ],
        )
    )
    client_transport, server_transport = memory_transport_pair()
    server = AppServer(
        server_transport,
        oidc_tenants=process_services.oidc_tenants,
        platform_credential_lenders=process_services.platform_credential_lenders,
        session_backend_host_factory=lambda _: host,
        host_handler=HostRequestHandler(
            HarnessFilesManager(sources=("user", "project")),
            org_config=process_services.org_config,
            worktrees=process_services.worktrees,
            experiments=process_services.experiments,
            model_catalog=process_services.model_catalog,
        ),
    )
    client = AppServerClient(
        client_transport,
        run_peer=lambda: server.serve_connection(
            server_transport, close_on_disconnect=False
        ),
    )
    await client.initialize(ClientInfo(name="editor", version="1"))
    await client.notify("initialized")
    await client.request(
        "session/resume", SessionResumeParams(session_id=backend.session_id)
    )
    await client.request(
        "session/turn/queue/edit/start",
        TurnQueueEditStartParams(
            session_id=backend.session_id,
            queue_item_id=queued.response.queue_item_id,
            edit_id=UUID("aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"),
        ),
    )

    # Do
    await client.close()
    next_client_transport, next_server_transport = memory_transport_pair()
    reconnected = AppServerClient(
        next_client_transport,
        run_peer=lambda: server.serve_connection(
            next_server_transport, close_on_disconnect=False
        ),
    )
    try:
        await reconnected.initialize(ClientInfo(name="editor", version="1"))
        await reconnected.notify("initialized")
        resumed = SessionReadResponse.model_validate(
            await reconnected.request(
                "session/resume", SessionResumeParams(session_id=backend.session_id)
            )
        )

        # Assert
        assert resumed.state.turn_queue.paused is True
        assert resumed.state.turn_queue.editing is None
        assert resumed.state.turn_queue.items[0].entries[0].content == [
            SessionTextContentBlock(text="original")
        ]
    finally:
        await reconnected.close()
        await server.close()


@pytest.mark.asyncio
async def test_unified_queued_steer_forwards_only_stored_queue_identity(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, process_services: ProcessServices
) -> None:
    """*Prepare*: A Unified adapter and an atomic queued-steer request.
    *Do*: Send the request through the adapter.
    *Assert*: The Harness receives only IDs and the response follows flushed events.
    """
    # Prepare
    pytest.importorskip("mistralai_vibe_local_harness.vibe")
    if getattr(harness_session_protocol, "TurnQueueSteerParams", None) is None:
        pytest.skip("installed Unified Harness does not support queued steering")
    monkeypatch.setenv("MISTRAL_API_KEY", "test-key")
    session = _RecordingSession()
    adapter = await _skill_adapter(tmp_path, session, process_services=process_services)
    flushed = False

    async def flush_events() -> None:
        nonlocal flushed
        flushed = True
        adapter._event_id = 7

    monkeypatch.setattr(adapter, "flush_events", flush_events)
    params = TurnQueueSteerParams(
        session_id="session-1", queue_item_id="queue-1", expected_turn_id="turn-1"
    )

    # Do
    result = await adapter.steer_queued_turn(params)

    # Assert
    harness_params = session.sent[-1]
    assert harness_params.model_dump(mode="json") == {
        "sessionId": "session-1",
        "queueItemId": "queue-1",
        "expectedTurnId": "turn-1",
    }
    assert flushed
    assert result.response == TurnQueueSteerResponse(
        queue_item_id="queue-1", turn_id="turn-1", last_event_id=7
    )


