def test_unified_read_projects_provider_retry_and_accepts_older_harness_state(
    tmp_path: Path,
) -> None:
    """*Prepare*: New and pre-retry-field Harness session snapshots.
    *Do*: Translate both snapshots through the Vibe backend adapter.
    *Assert*: Retry state is projected when present and absent state remains compatible.
    """
    # Prepare
    pytest.importorskip("mistralai_vibe_local_harness.vibe")
    from mistralai_vibe_local_harness.session_protocol import (
        IdleSessionStatus,
        LatestPublicHistoryPage,
        PublicSession as HarnessPublicSession,
        TurnQueue as HarnessTurnQueue,
    )
    from vibe.app_server._session_projection import read_response

    state = {
        "session": HarnessPublicSession(
            id="session-root", status=IdleSessionStatus(), created_at=1, updated_at=1
        ),
        "history": LatestPublicHistoryPage(entries=[]),
        "active_callbacks": [],
        "latest_turn": None,
        "turn_queue": HarnessTurnQueue(items=[], paused=False, max_items=32),
    }

    # Do
    retrying = read_response(
        cast(
            Any,
            SimpleNamespace(
                state=SimpleNamespace(
                    **state,
                    retrying=SimpleNamespace(
                        turn_id="turn-1",
                        category="rate_limited",
                        detail="HTTP 429",
                        retry_at=1_700_000_000_000,
                        retry_attempt=3,
                    ),
                ),
                watermark=1,
            ),
        ),
        str(tmp_path),
        scheduled_loops=[],
        goal=None,
        goal_notices=(),
        mcp_apps=None,
        started_by_session_id=None,
    )
    older_harness = read_response(
        cast(Any, SimpleNamespace(state=SimpleNamespace(**state), watermark=2)),
        str(tmp_path),
        scheduled_loops=[],
        goal=None,
        goal_notices=(),
        mcp_apps=None,
        started_by_session_id=None,
    )

    # Assert
    assert retrying.state.retrying == PublicRetryState(
        turn_id="turn-1",
        category=PublicRetryCategory.RATE_LIMITED,
        detail="HTTP 429",
        retry_at=1_700_000_000_000,
        retry_attempt=3,
    )
    assert older_harness.state.retrying is None


def test_unified_read_projects_scheduled_loops_into_session(tmp_path: Path) -> None:
    """*Prepare*: A session snapshot plus stored interval and cron loops.
    *Do*: Translate the snapshot through the Vibe backend adapter.
    *Assert*: The session summary carries the loops with their recurrence and
    next fire time.
    """
    # Prepare
    pytest.importorskip("mistralai_vibe_local_harness.vibe")
    from mistralai_vibe_local_harness.session_protocol import (
        IdleSessionStatus,
        LatestPublicHistoryPage,
        PublicSession as HarnessPublicSession,
        TurnQueue as HarnessTurnQueue,
    )
    from vibe.app_server._session_projection import read_response
    from vibe.app_server._unified_scheduled_loops import ScheduledPrompt
    from vibe.app_server.models import ScheduledLoop as PublicScheduledLoop

    snapshot = SimpleNamespace(
        state=SimpleNamespace(
            session=HarnessPublicSession(
                id="session-root",
                status=IdleSessionStatus(),
                created_at=1,
                updated_at=1,
            ),
            history=LatestPublicHistoryPage(entries=[]),
            active_callbacks=[],
            latest_turn=None,
            turn_queue=HarnessTurnQueue(items=[], paused=False, max_items=32),
        ),
        watermark=1,
    )
    loops = [
        ScheduledPrompt(
            id="loop-1",
            interval_seconds=3600,
            prompt="Check the CI pipeline",
            next_fire_at=1_800_000_000.0,
            created_at=1_700_000_000.0,
        ),
        ScheduledPrompt(
            id="loop-2",
            cron="0 9 * * 1",
            prompt="Summarize the week",
            next_fire_at=1_800_100_000.0,
            created_at=1_700_000_000.0,
        ),
    ]

    # Do
    response = read_response(
        cast(Any, snapshot),
        str(tmp_path),
        scheduled_loops=loops,
        goal=None,
        goal_notices=(),
        started_by_session_id=None,
        mcp_apps=None,
    )

    # Assert
    expected = [
        PublicScheduledLoop(
            id="loop-1",
            prompt="Check the CI pipeline",
            interval_seconds=3600,
            next_fire_at=1_800_000_000.0,
        ),
        PublicScheduledLoop(
            id="loop-2",
            prompt="Summarize the week",
            cron="0 9 * * 1",
            next_fire_at=1_800_100_000.0,
        ),
    ]
    assert response.state.session.loops == expected
    # Without stored loops the additive field stays an empty list.
    assert (
        read_response(
            cast(Any, snapshot),
            str(tmp_path),
            scheduled_loops=[],
            goal=None,
            goal_notices=(),
            started_by_session_id=None,
            mcp_apps=None,
        ).state.session.loops
        == []
    )


