    # Assert
    assert refused.value.data == {"kind": "configuration"}
    assert str(refused.value) == _LEAN_CLASHES_WITH_CONFIG_TOML
    assert backend._context is previous
    assert backend._context.agents.active_agent.name == "lean"
    assert notices == []


