@pytest.mark.asyncio
async def test_unified_session_start_skips_the_fetch_when_flag_off(
    monkeypatch: pytest.MonkeyPatch, process_services: ProcessServices
) -> None:
    pytest.importorskip("mistralai_vibe_local_harness.vibe")
